    bool DidIWin = false;
    int countReachedStates = 0;
    if (userstates.Count > 0)
    {
        UsersStates usersState = userstates.FirstOrDefault();

        player.ActiveCard = usersState.CardId;           
        var States = _context.States.Where(a => true).ToList();
        foreach(States state in States)
        {
            var sum = userstates.Where(a=>a.StateId==state.Id.ToString()).Sum(a => a.Points);
            var stateSum = new StateSummary();
            stateSum.points = sum;
            stateSum.pointsName = state.Points;
            stateSum.name = state.State;
            stateSum.Id = state.Id;
            stateSum.finalPoints = 600;
            if(stateSum.finalPoints<=sum)
            {
                countReachedStates++;
            }
            myStates.Add(stateSum);
        }

        if(countReachedStates>=States.Count)
        {
            DidIWin = true;
        }
        string lastAction = "";
        int actionNum = 1;
        foreach(UsersStates userstate in userstates)
        {

            TeamHistoryMoves newmove = new TeamHistoryMoves();
            newmove.ActionId = userstate.ActionId;
            newmove.CardId = userstate.CardId;
            newmove.ActionNum = actionNum;
            newmove.Explanation = "";
            newmove.StateId = userstate.StateId;
            newmove.Points = usersState.Points;
            newmove.Id = Guid.NewGuid();
            if (lastAction != newmove.ActionId)
            {
                actionNum++;
            }
            lastAction = usersState.ActionId;
            moves.Add(newmove);

        }

    }
    player.Status = "Choose Action";
    player.moves = moves;

    if (DidIWin)
    {
        player.Status = "Won";
    }

    player.States = myStates;     
